    <title>Image Preview | Aurora Library</title>
    <style>
      :root {
        color-scheme: dark;
        --color-bg: #0b1020;
        --color-surface: #141b2d;
        --color-surface-elevated: #1b2440;
        --color-text: #f3f6ff;
        --color-muted-text: #b2bdd6;
        --color-border: #313d61;
        --color-focus: #93c5fd;
        --color-danger: #ff7b8a;
        --color-danger-strong: #ff5b6e;
        --color-danger-surface: #351722;
        --color-accent: #8b9cff;
        --shadow-lg: 0 28px 70px rgba(0, 0, 0, 0.45);
        --shadow-md: 0 18px 40px rgba(0, 0, 0, 0.35);
        --radius-lg: 24px;
        --radius-md: 18px;
        --radius-sm: 12px;
      }

      * {
        box-sizing: border-box;
      }

      html {
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        background: var(--color-bg);
        color: var(--color-text);
      }

      body {
        margin: 0;
        min-height: 100vh;
        background:
          radial-gradient(circle at top, #182241 0, var(--color-bg) 42%),
          linear-gradient(180deg, #0d1326 0%, var(--color-bg) 100%);
      }

      a,
      button {
        font: inherit;
      }

      button {
        cursor: pointer;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        padding: 0.8rem 1rem;
        border-radius: var(--radius-sm);
        background: var(--color-text);
        color: var(--color-bg);
        text-decoration: none;
        transform: translateY(-140%);
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .shell {
        width: min(100%, 72rem);
        margin: 0 auto;
        padding: 2rem 1rem 4rem;
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--color-accent);
        font-size: 0.95rem;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 5vw, 3.8rem);
        line-height: 1.05;
      }

      .intro {
        max-width: 40rem;
        margin: 1rem 0 0;
        color: var(--color-muted-text);
        font-size: 1.05rem;
        line-height: 1.6;
      }

      .preview-layout {
        display: grid;
        gap: 1.5rem;
        margin-top: 2rem;
      }

      .preview-card,
      .details-card {
        background: linear-gradient(180deg, #18213a 0%, var(--color-surface) 100%);
        border: 1px solid var(--color-border);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow-md);
      }

      .preview-card {
        overflow: hidden;
      }

      figure {
        margin: 0;
      }

      .image-frame {
        padding: 1rem;
      }

      .image-frame img,
      .image-placeholder {
        display: block;
        width: 100%;
        aspect-ratio: 16 / 10;
        border-radius: calc(var(--radius-lg) - 8px);
        border: 1px solid #42507a;
        object-fit: cover;
        background: #0f1528;
      }

      .image-placeholder {
        display: grid;
        place-items: center;
        padding: 2rem;
        color: var(--color-muted-text);
        text-align: center;
      }

      figcaption,
      .details-card {
        padding: 1.25rem 1.25rem 1.5rem;
      }

      .meta-grid {
        display: grid;
        gap: 0.85rem;
        grid-template-columns: repeat(auto-fit, minmax(11rem, 1fr));
        margin-top: 1rem;
      }

      .meta-item {
        padding: 0.9rem 1rem;
        background: #11182d;
        border: 1px solid var(--color-border);
        border-radius: var(--radius-sm);
      }

      .meta-label {
        display: block;
        color: var(--color-muted-text);
        font-size: 0.9rem;
      }

      .meta-value {
        display: block;
        margin-top: 0.35rem;
        font-weight: 600;
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.85rem;
        margin-top: 1.5rem;
      }

      .button {
        min-height: 2.875rem;
        padding: 0.8rem 1.15rem;
        border: 1px solid transparent;
        border-radius: 999px;
        color: var(--color-text);
        background: var(--color-surface-elevated);
      }

      .button:hover {
        background: #243052;
      }

      .button-danger {
        border-color: #a63f52;
        background: var(--color-danger-surface);
      }

      .button-danger:hover {
        background: #451d2a;
      }

      .button-solid {
        background: var(--color-danger-strong);
        border-color: var(--color-danger-strong);
        color: #18060b;
        font-weight: 700;
      }

      .button-solid:hover {
        background: #ff7080;
        border-color: #ff7080;
      }

      .button:focus-visible,
      .skip-link:focus-visible,
      dialog button:focus-visible {
        outline: 3px solid var(--color-focus);
        outline-offset: 3px;
      }

      .status-message {
        margin-top: 1.5rem;
        padding: 1rem 1.1rem;
        border: 1px solid #406b57;
        border-radius: var(--radius-sm);
        background: #13261f;
        color: #d7f9e4;
      }

      .status-message[hidden] {
        display: none;
      }

      .details-card h2,
      dialog h2 {
        margin: 0 0 0.85rem;
        font-size: 1.35rem;
      }

      .details-card p,
      dialog p,
      figcaption p {
        margin: 0;
        color: var(--color-muted-text);
        line-height: 1.6;
      }

      dialog {
        width: min(100% - 2rem, 32rem);
        padding: 0;
        border: 1px solid var(--color-border);
        border-radius: var(--radius-md);
        background: linear-gradient(180deg, #1b2340 0%, #12192c 100%);
        color: var(--color-text);
        box-shadow: var(--shadow-lg);
      }

      dialog::backdrop {
        background: rgba(5, 8, 16, 0.78);
        backdrop-filter: blur(6px);
      }

      .dialog-inner {
        padding: 1.5rem;
      }

      .dialog-icon {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 2.75rem;
        height: 2.75rem;
        margin-bottom: 1rem;
        border-radius: 999px;
        background: var(--color-danger-surface);
        color: var(--color-danger);
        border: 1px solid #934151;
        font-size: 1.4rem;
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        justify-content: flex-end;
        margin-top: 1.5rem;
      }

      @media (min-width: 56rem) {
        .preview-layout {
          grid-template-columns: minmax(0, 1.55fr) minmax(18rem, 0.95fr);
          align-items: start;
        }
      }

      @media (max-width: 32rem) {
        .shell {
          padding-inline: 0.85rem;
        }

        .actions,
        .dialog-actions {
          flex-direction: column;
        }

        .actions .button,
        .dialog-actions .button {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        .preview-card,
        .details-card,
        .meta-item,
        dialog,
        .status-message,
        .image-frame img,
        .image-placeholder {
          border-color: CanvasText;
        }

        .button,
        .button-danger,
        .button-solid,
        .skip-link {
          border: 2px solid ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>

    <main id="maincontent" class="shell" tabindex="-1">
      <p class="eyebrow">Aurora Library</p>
      <h1>Image preview</h1>
      <p class="intro">
        Review the selected image, inspect its library details, and remove it only if you are sure
        you no longer want to keep it in your collection.
      </p>

      <section class="preview-layout" aria-label="Image details">
        <article class="preview-card">
          <figure>
            <div class="image-frame" id="imageFrame">
              <img
                id="previewImage"
                src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1600 1000'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' x2='1' y1='0' y2='1'%3E%3Cstop stop-color='%23111c38'/%3E%3Cstop offset='1' stop-color='%23366385'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='1600' height='1000' fill='url(%23g)'/%3E%3Ccircle cx='1280' cy='180' r='88' fill='%23f7c873'/%3E%3Cpath d='M0 710 250 520l220 145 235-250 170 150 145-85 300 230H0Z' fill='%23243d57'/%3E%3Cpath d='M0 820 290 610l190 115 220-180 150 110 150-95 600 260H0Z' fill='%233c5f77'/%3E%3Cpath d='M0 905 330 720l220 110 210-125 145 78 195-110 500 232H0Z' fill='%2364a0a8'/%3E%3C/svg%3E"
                alt="A stylized landscape with layered mountains under a glowing moon."
              >
            </div>
            <figcaption>
              <h2 id="imageTitle">Moonlit ridgeline</h2>
              <p id="imageDescription">
                Uploaded to your inspiration library and tagged for the next travel campaign.
              </p>
            </figcaption>
          </figure>
        </article>

        <aside class="details-card" aria-labelledby="detailsHeading">
          <h2 id="detailsHeading">Library details</h2>
          <p>The delete action opens a confirmation dialog and keeps the image intact until you approve it.</p>

          <div class="meta-grid">
            <div class="meta-item">
              <span class="meta-label">Filename</span>
              <span class="meta-value" id="fileName">moonlit-ridgeline.jpg</span>
            </div>
            <div class="meta-item">
              <span class="meta-label">Resolution</span>
              <span class="meta-value">1600 x 1000</span>
            </div>
            <div class="meta-item">
              <span class="meta-label">Collection</span>
              <span class="meta-value">Travel concepts</span>
            </div>
            <div class="meta-item">
              <span class="meta-label">License</span>
              <span class="meta-value">Internal library</span>
            </div>
          </div>

          <div class="actions" id="actionArea">
            <button type="button" class="button">Download original</button>
            <button type="button" class="button button-danger trigger" id="openDialog">
              Delete image
            </button>
          </div>

          <p id="statusMessage" class="status-message" role="status" aria-live="polite" hidden tabindex="-1"></p>
        </aside>
      </section>
    </main>

    <dialog id="deleteDialog" aria-labelledby="dialogTitle" aria-describedby="dialogDescription">
      <div class="dialog-inner">
        <div class="dialog-icon" aria-hidden="true">!</div>
        <h2 id="dialogTitle">Delete this image from your library?</h2>
        <p id="dialogDescription">
          This removes <strong>moonlit-ridgeline.jpg</strong> from Aurora Library. You can cancel to
          keep the image available.
        </p>
        <div class="dialog-actions">
          <button type="button" class="button" id="cancelDialog" autofocus>Cancel</button>
          <button type="button" class="button button-solid" id="confirmDelete">Delete image</button>
        </div>
      </div>
    </dialog>

    <script>
      const dialog = document.getElementById("deleteDialog");
      const trigger = document.getElementById("openDialog");
      const cancelButton = document.getElementById("cancelDialog");
      const confirmButton = document.getElementById("confirmDelete");
      const imageFrame = document.getElementById("imageFrame");
      const imageTitle = document.getElementById("imageTitle");
      const imageDescription = document.getElementById("imageDescription");
      const actionArea = document.getElementById("actionArea");
      const statusMessage = document.getElementById("statusMessage");
      const fileName = document.getElementById("fileName");

      trigger.addEventListener("click", () => {
        dialog.showModal();
      });

      cancelButton.addEventListener("click", () => {
        dialog.close("cancel");
      });

      confirmButton.addEventListener("click", () => {
        dialog.close("delete");
      });

      dialog.addEventListener("close", () => {
        if (dialog.returnValue !== "delete") {
          return;
        }

        imageFrame.innerHTML =
          '<div class="image-placeholder">The image has been deleted from your library.</div>';
        imageTitle.textContent = "Image removed";
        imageDescription.textContent =
          "This preview is no longer available because the image was deleted from Aurora Library.";
        actionArea.innerHTML = '<button type="button" class="button" disabled>Image deleted</button>';
        fileName.textContent = "Deleted";
        statusMessage.hidden = false;
        statusMessage.textContent = "Image deleted from your library.";
        statusMessage.focus();
      });
    </script>
  </body>
</html>
