const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');
const axeSource = require('axe-core').source;

(async () => {
  const htmlPath = '/workspace/sandbox/skills/building-accessible-ui/modal-dialog--framework-vanilla-js--style-dark/gpt-5.4__s1/index.html';
  const html = fs.readFileSync(htmlPath, 'utf8');
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });

  async function runAudit(state) {
    await page.setContent(html, { waitUntil: 'load' });
    await page.addScriptTag({ content: axeSource });
    if (state === 'dialog-open') {
      await page.click('#openDialog');
    }
    const results = await page.evaluate(async () => {
      const run = await window.axe.run();
      return run.violations.map((v) => ({
        id: v.id,
        impact: v.impact,
        tags: v.tags,
        targets: v.nodes.map((n) => n.target)
      }));
    });
    return results;
  }

  const all = {
    default: await runAudit('default'),
    'dialog-open': await runAudit('dialog-open')
  };
  const wcag = Object.fromEntries(
    Object.entries(all).map(([state, violations]) => [
      state,
      violations.filter((v) => !v.tags.includes('best-practice'))
    ])
  );

  console.log(JSON.stringify({ wcag, all }));
  await browser.close();
  process.exit(Object.values(wcag).some((list) => list.length) ? 1 : 0);
})().catch((error) => {
  console.error(error);
  process.exit(3);
});
