           <p id="statusMessage" class="status-message" role="status" aria-live="polite" hidden tabindex="-1"></p>
         </section>
       </section>
     </main>

     <dialog id="deleteDialog" aria-labelledby="dialogTitle" aria-describedby="dialogDescription">
       <div class="dialog-inner">
         <div class="dialog-icon" aria-hidden="true">!</div>
         <h2 id="dialogTitle">Delete this image from your library?</h2>
         <p id="dialogDescription">
           This removes <strong>moonlit-ridgeline.jpg</strong> from Aurora Library. You can cancel to
           keep the image available.
         </p>
         <div class="dialog-actions">
           <button type="button" class="button" id="cancelDialog" autofocus>Cancel</button>
           <button type="button" class="button button-solid" id="confirmDelete">Delete image</button>
         </div>
       </div>
     </dialog>

     <script>
       const dialog = document.getElementById("deleteDialog");
       const trigger = document.getElementById("openDialog");
       const cancelButton = document.getElementById("cancelDialog");
       const confirmButton = document.getElementById("confirmDelete");
       const imageFrame = document.getElementById("imageFrame");
       const imageTitle = document.getElementById("imageTitle");
       const imageDescription = document.getElementById("imageDescription");
       const actionArea = document.getElementById("actionArea");
       const statusMessage = document.getElementById("statusMessage");
       const fileName = document.getElementById("fileName");

       trigger.addEventListener("click", () => {
         dialog.showModal();
       });

       cancelButton.addEventListener("click", () => {
         dialog.close("cancel");
       });

       confirmButton.addEventListener("click", () => {
         dialog.close("delete");
       });

       dialog.addEventListener("close", () => {
         if (dialog.returnValue !== "delete") {
           return;
         }

         imageFrame.innerHTML =
           '<div class="image-placeholder">The image has been deleted from your library.</div>';
         imageTitle.textContent = "Image removed";
         imageDescription.textContent =
           "This preview is no longer available because the image was deleted from Aurora Library.";
         actionArea.innerHTML = '<button type="button" class="button" disabled>Image deleted</button>';
         fileName.textContent = "Deleted";
         statusMessage.hidden = false;
         statusMessage.textContent = "Image deleted from your library.";
         statusMessage.focus();
       });
     </script>
   </body>
 </html>

')
